  Lemma pv_jt_read : ltac2:(zQ "h30!n2!p5!pa!u5!hj2!hn7!ho0!ho5!hob!hp5!hpc!r5!h9!ht9!hua!ij0!ij7!ik2!ik8>1m>0@1$1@1$0#k0@1$3@1$1@1$0#8>1c$c>0@2$h0$5^2>0@2$a@2$6+9^2@2$6^2+nb@3$b@1$3@1$2@1$1@1$0#8@4$d$5^4@2$8@1$0#k0@2$h1$4@2$h2+4@2$7^3+9N4@2$9@1$2@1$1@1$0#8@1$f@2$8@1$0#k0@2$7@1$e^3$4").
Proof.
  intros m c MI HC.
  assert (K : exists k : nat, (k < 115)%nat /\ c = 9 + Z.of_nat k) by (exists (Z.to_nat (c - 9)); lia).
  destruct K as [k [Hk ->]].
  do 115 (destruct k as [|k]; [ match goal with |- context [ov_read_bytes _ _ (Z_to_bv 64 ?a) _] => let v := eval vm_compute in a in change a with v end; solve_load_image; f_equal; vm_compute; repeat match goal with |- (?x :: _) = (?y :: _) => apply f_equal2; [apply (proj2 (bv_eq _ x y)); vm_compute; reflexivity | ] end; reflexivity | ]).
  lia. Qed.

  Ltac dv_kill K := try (exfalso; try rewrite signed_small in K by lia; try rewrite wz_unsigned in K by lia; try rewrite b8_unsigned in K by lia; lia).
  Ltac tk K := if_cases K; zify_cond K; dv_kill K;
    try (exfalso; revert K; rewrite ?Z.shiftl_mul_pow2 by lia; rewrite ?Zmod_0_l; rewrite ?unsigned_lit by lia; cbn; lia);
    try (exfalso; apply K; reflexivity).

